contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0));

        address owner = c.owner();
        uint256 balBefore = address(c).balance;
        uint256 recBefore = recipient.balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (msg.sender == owner) {
            assert(!reverted);
            assert(address(c).balance == 0);
            assert(recipient.balance == recBefore + balBefore);
        } else {
            assert(reverted);
            assert(address(c).balance == balBefore);
            assert(recipient.balance == recBefore);
        }
    }

    receive() external payable {}
}

