contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner, address _caller, address _recipient) public payable {
        require(address(this).balance >= 0);

        uint256 beforeC = address(c).balance;
        uint256 beforeR = _recipient.balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (_caller == _owner) {
            assert(!reverted && _recipient.balance == beforeR + beforeC && address(c).balance == 0);
        } else {
            assert(reverted && address(c).balance == beforeC && _recipient.balance == beforeR);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner, address _recipient) public payable {
        require(address(this).balance >= 0);
        require(address(this) == _owner, "inv: caller is not owner");

        uint256 beforeC = address(c).balance;
        uint256 beforeR = _recipient.balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(c).balance == 0 && _recipient.balance == beforeR + beforeC);
    }

    receive() external payable {}
}
